import{_ as t,c as a,o as h,a2 as o}from"./chunks/framework.B7el9cAC.js";const p=JSON.parse('{"title":"Mục 2.5 – Internet và Dịch Vụ Internet","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-2/2.5-internet-dich-vu.md","filePath":"chuong-2/2.5-internet-dich-vu.md","lastUpdated":1775359730000}'),i={name:"chuong-2/2.5-internet-dich-vu.md"};function e(r,n,s,g,c,l){return h(),a("div",null,[...n[0]||(n[0]=[o(`<h1 id="muc-2-5-–-internet-va-dich-vu-internet" tabindex="-1">Mục 2.5 – Internet và Dịch Vụ Internet <a class="header-anchor" href="#muc-2-5-–-internet-va-dich-vu-internet" aria-label="Permalink to &quot;Mục 2.5 – Internet và Dịch Vụ Internet&quot;">​</a></h1><blockquote><p><strong>Chương 2: Mạng máy tính và Internet</strong></p></blockquote><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><h3 id="internet-la-gi-va-tu-đau-đen" tabindex="-1">Internet là gì và từ đâu đến? <a class="header-anchor" href="#internet-la-gi-va-tu-đau-đen" aria-label="Permalink to &quot;Internet là gì và từ đâu đến?&quot;">​</a></h3><p>Hãy tưởng tượng thế giới như một thành phố khổng lồ với hàng tỷ ngôi nhà. Mỗi ngôi nhà là một máy tính. <strong>Internet</strong> chính là hệ thống đường giao thông nối tất cả các ngôi nhà đó lại với nhau – bất kể bạn ở Việt Nam hay Mỹ, bất kể máy tính bạn là PC hay điện thoại.</p><p>Internet không thuộc sở hữu của bất kỳ ai và không có &quot;trung tâm điều khiển&quot;. Nó là <strong>mạng của các mạng</strong> – hàng triệu mạng nhỏ (LAN, WAN của công ty, trường học, nhà cung cấp dịch vụ...) kết nối lại với nhau thông qua giao thức TCP/IP.</p><p><strong>Một số dịch vụ chạy trên Internet:</strong></p><ul><li>Bạn lướt web → dùng dịch vụ <strong>WWW (World Wide Web)</strong></li><li>Bạn gửi email → dùng dịch vụ <strong>Email</strong></li><li>Bạn tải file → dùng dịch vụ <strong>FTP</strong></li><li>Bạn chat realtime → dùng dịch vụ <strong>Instant Messaging / VoIP</strong></li></ul><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="_2-1-internet-la-gi" tabindex="-1">2.1 Internet là gì? <a class="header-anchor" href="#_2-1-internet-la-gi" aria-label="Permalink to &quot;2.1 Internet là gì?&quot;">​</a></h3><p><strong>Internet (International Network)</strong> là hệ thống <strong>mạng máy tính toàn cầu</strong> kết nối hàng tỷ thiết bị với nhau thông qua bộ giao thức <strong>TCP/IP</strong>.</p><ul><li>Hình thành từ mạng ARPANET (Bộ Quốc phòng Mỹ, 1969) – ban đầu phục vụ quân sự và nghiên cứu.</li><li>Mở rộng ra toàn thế giới vào những năm 1990 khi Tim Berners-Lee phát minh ra <strong>WWW</strong>.</li><li>Hiện nay kết nối hơn <strong>5 tỷ người dùng</strong> trên toàn thế giới.</li><li>Được kết nối vật lý qua hệ thống cáp biển, vệ tinh, và cáp quang trên đất liền.</li></ul><h3 id="_2-2-world-wide-web-www" tabindex="-1">2.2 World Wide Web (WWW) <a class="header-anchor" href="#_2-2-world-wide-web-www" aria-label="Permalink to &quot;2.2 World Wide Web (WWW)&quot;">​</a></h3><p><strong>WWW (World Wide Web)</strong> là hệ thống tài liệu siêu văn bản (hypertext) liên kết với nhau, được truy cập qua Internet bằng trình duyệt web.</p><blockquote><p>⚠️ <strong>Lưu ý quan trọng:</strong> WWW <strong>không phải là Internet</strong>. WWW là <strong>một dịch vụ chạy trên Internet</strong> – cũng như email hay FTP là các dịch vụ khác.</p></blockquote><p><strong>Các thành phần của WWW:</strong></p><table tabindex="0"><thead><tr><th>Thành phần</th><th>Giải thích</th></tr></thead><tbody><tr><td><strong>URL</strong></td><td>Địa chỉ tài nguyên trên web: <code>https://www.google.com/search</code></td></tr><tr><td><strong>HTTP/HTTPS</strong></td><td>Giao thức truyền tải trang web</td></tr><tr><td><strong>HTML</strong></td><td>Ngôn ngữ đánh dấu xây dựng trang web</td></tr><tr><td><strong>Web Browser</strong></td><td>Phần mềm hiển thị trang web (Chrome, Firefox...)</td></tr><tr><td><strong>Web Server</strong></td><td>Máy chủ lưu trữ và phục vụ trang web</td></tr></tbody></table><p><strong>Giao thức HTTP vs HTTPS:</strong></p><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>HTTP</th><th>HTTPS</th></tr></thead><tbody><tr><td><strong>Viết tắt</strong></td><td>HyperText Transfer Protocol</td><td>HTTP Secure</td></tr><tr><td><strong>Mã hóa</strong></td><td>Không</td><td>Có (SSL/TLS)</td></tr><tr><td><strong>Cổng mặc định</strong></td><td>80</td><td>443</td></tr><tr><td><strong>Biểu tượng trình duyệt</strong></td><td>⚠️ &quot;Không an toàn&quot;</td><td>🔒 Khóa xanh</td></tr><tr><td><strong>Dùng cho</strong></td><td>Website thông thường cũ</td><td>Mọi website hiện đại, ngân hàng, mua sắm</td></tr></tbody></table><h3 id="_2-3-ten-mien-domain-name-va-dns" tabindex="-1">2.3 Tên miền (Domain Name) và DNS <a class="header-anchor" href="#_2-3-ten-mien-domain-name-va-dns" aria-label="Permalink to &quot;2.3 Tên miền (Domain Name) và DNS&quot;">​</a></h3><h4 id="ten-mien-la-gi" tabindex="-1">Tên miền là gì? <a class="header-anchor" href="#ten-mien-la-gi" aria-label="Permalink to &quot;Tên miền là gì?&quot;">​</a></h4><p><strong>Tên miền (Domain Name)</strong> là địa chỉ dễ nhớ để trỏ đến máy chủ web, thay vì phải nhớ địa chỉ IP dạng số.</p><p><strong>Ví dụ:</strong></p><ul><li>Thay vì nhớ địa chỉ IP số của Google, bạn chỉ cần nhớ <code>google.com</code></li><li>Thay vì nhớ địa chỉ IP số của VnExpress, bạn chỉ cần nhớ <code>vnexpress.net</code></li></ul><blockquote><p><em>(Địa chỉ IP cụ thể của các trang web có thể thay đổi theo thời gian – điều quan trọng là tên miền luôn ổn định cho dù IP thay đổi.)</em></p></blockquote><p><strong>Cấu trúc tên miền:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://  www  .  google  .  com  /  search  ?  q=tin+hoc</span></span>
<span class="line"><span> Giao      ──   Tên miền    Tên   ──  Đường   ──  Tham số</span></span>
<span class="line"><span> thức    phụ   cấp hai     miền     dẫn       truy vấn</span></span>
<span class="line"><span>              (sub)        cấp</span></span>
<span class="line"><span>                           cao</span></span></code></pre></div><p><strong>Các loại tên miền cấp cao (TLD – Top Level Domain):</strong></p><table tabindex="0"><thead><tr><th>TLD</th><th>Ý nghĩa</th><th>Ví dụ</th></tr></thead><tbody><tr><td><code>.com</code></td><td>Thương mại (commercial)</td><td>google.com, facebook.com</td></tr><tr><td><code>.edu</code></td><td>Giáo dục (education)</td><td>mit.edu, hust.edu.vn</td></tr><tr><td><code>.gov</code></td><td>Chính phủ (government)</td><td>whitehouse.gov, chinhphu.vn</td></tr><tr><td><code>.org</code></td><td>Tổ chức phi lợi nhuận</td><td>wikipedia.org</td></tr><tr><td><code>.net</code></td><td>Mạng lưới (network)</td><td>speedtest.net</td></tr><tr><td><code>.vn</code></td><td>Việt Nam (country code)</td><td>vnexpress.net, moet.gov.vn</td></tr></tbody></table><h4 id="dns-la-gi" tabindex="-1">DNS là gì? <a class="header-anchor" href="#dns-la-gi" aria-label="Permalink to &quot;DNS là gì?&quot;">​</a></h4><p><strong>DNS (Domain Name System)</strong> là hệ thống <strong>dịch tên miền sang địa chỉ IP</strong> và ngược lại.</p><p>DNS hoạt động như <strong>danh bạ điện thoại của Internet</strong> – bạn tra tên người → DNS trả về số điện thoại (địa chỉ IP).</p><p><strong>Quá trình phân giải DNS:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bạn gõ: www.google.com</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[Trình duyệt] → Kiểm tra cache (đã biết IP chưa?)</span></span>
<span class="line"><span>        ↓ Chưa biết</span></span>
<span class="line"><span>[DNS Resolver] → Hỏi DNS Server của ISP</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[DNS Server ISP] → Hỏi Root DNS Server (.com)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[Root DNS] → Chuyển đến DNS của Google</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[DNS Google] → Trả về IP: 142.250.196.46</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[Trình duyệt] → Kết nối đến IP 142.250.196.46</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Trang Google hiện ra!</span></span></code></pre></div><h3 id="_2-4-email-va-cac-giao-thuc-email" tabindex="-1">2.4 Email và các giao thức email <a class="header-anchor" href="#_2-4-email-va-cac-giao-thuc-email" aria-label="Permalink to &quot;2.4 Email và các giao thức email&quot;">​</a></h3><p><strong>Email (Electronic Mail)</strong> là dịch vụ gửi và nhận thư điện tử qua Internet.</p><p><strong>Cấu trúc địa chỉ email:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nguyenvana  @  gmail  .  com</span></span>
<span class="line"><span>   ────────    ──────    ───</span></span>
<span class="line"><span>  Tên người    Tên nhà   TLD</span></span>
<span class="line"><span>   dùng        cung cấp</span></span></code></pre></div><p><strong>Các giao thức email:</strong></p><table tabindex="0"><thead><tr><th>Giao thức</th><th>Viết tắt</th><th>Cổng</th><th>Chức năng</th></tr></thead><tbody><tr><td><strong>SMTP</strong></td><td>Simple Mail Transfer Protocol</td><td>25 (587 có TLS)</td><td><strong>Gửi</strong> email từ máy khách → máy chủ, và giữa các máy chủ</td></tr><tr><td><strong>POP3</strong></td><td>Post Office Protocol v3</td><td>110 (995 có SSL)</td><td><strong>Nhận</strong> email – tải về máy và xóa khỏi server</td></tr><tr><td><strong>IMAP</strong></td><td>Internet Message Access Protocol</td><td>143 (993 có SSL)</td><td><strong>Nhận</strong> email – đồng bộ với server, truy cập từ nhiều thiết bị</td></tr></tbody></table><blockquote><p><strong>Nhớ đơn giản:</strong> SMTP = <strong>Gửi</strong>, POP3/IMAP = <strong>Nhận</strong><strong>POP3 vs IMAP:</strong> POP3 tải về máy và xóa server → chỉ dùng được 1 thiết bị. IMAP đồng bộ với server → dùng nhiều thiết bị (điện thoại, máy tính, tablet cùng thấy hộp thư).</p></blockquote><h3 id="_2-5-ftp-–-truyen-file-qua-mang" tabindex="-1">2.5 FTP – Truyền file qua mạng <a class="header-anchor" href="#_2-5-ftp-–-truyen-file-qua-mang" aria-label="Permalink to &quot;2.5 FTP – Truyền file qua mạng&quot;">​</a></h3><p><strong>FTP (File Transfer Protocol)</strong> là giao thức dùng để <strong>tải lên (upload) hoặc tải xuống (download) file</strong> từ/lên máy chủ qua mạng.</p><ul><li>Dùng cổng <strong>21</strong> (FTP) và <strong>20</strong> (truyền dữ liệu thực tế).</li><li><strong>FTPS</strong> và <strong>SFTP</strong> là phiên bản bảo mật của FTP (có mã hóa).</li><li>Ngày nay, FTP dần được thay thế bởi HTTPS và các dịch vụ lưu trữ đám mây (Google Drive, OneDrive...).</li></ul><p><strong>Ứng dụng thực tế:</strong></p><ul><li>Web developer dùng FTP/SFTP để upload file HTML, CSS, PHP lên hosting.</li><li>Công ty dùng FTP server nội bộ để chia sẻ file lớn.</li></ul><h3 id="_2-6-cac-dich-vu-internet-khac" tabindex="-1">2.6 Các dịch vụ Internet khác <a class="header-anchor" href="#_2-6-cac-dich-vu-internet-khac" aria-label="Permalink to &quot;2.6 Các dịch vụ Internet khác&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dịch vụ</th><th>Giao thức</th><th>Chức năng</th><th>Ví dụ</th></tr></thead><tbody><tr><td><strong>Truy cập web</strong></td><td>HTTP/HTTPS</td><td>Xem trang web</td><td>Google, Facebook, Zalo Web</td></tr><tr><td><strong>Email</strong></td><td>SMTP/POP3/IMAP</td><td>Gửi nhận thư điện tử</td><td>Gmail, Outlook, Yahoo Mail</td></tr><tr><td><strong>Chat/Nhắn tin</strong></td><td>XMPP, WebSocket</td><td>Nhắn tin thời gian thực</td><td>Messenger, Zalo, Telegram</td></tr><tr><td><strong>Gọi video</strong></td><td>RTP/WebRTC</td><td>Gọi điện/video call</td><td>Zoom, Google Meet, Skype</td></tr><tr><td><strong>Truyền file</strong></td><td>FTP/SFTP</td><td>Upload/download file</td><td>FileZilla, WinSCP</td></tr><tr><td><strong>Điều khiển từ xa</strong></td><td>SSH, RDP</td><td>Điều khiển máy tính từ xa</td><td>PuTTY, Remote Desktop</td></tr><tr><td><strong>Streaming</strong></td><td>HLS, RTMP</td><td>Phát video trực tiếp</td><td>YouTube, Netflix, TikTok</td></tr><tr><td><strong>DNS</strong></td><td>DNS</td><td>Phân giải tên miền → IP</td><td>Google DNS (8.8.8.8)</td></tr></tbody></table><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="internet-www" tabindex="-1">Internet ≠ WWW <a class="header-anchor" href="#internet-www" aria-label="Permalink to &quot;Internet ≠ WWW&quot;">​</a></h3><p>Đây là nhầm lẫn rất phổ biến, kể cả với người lớn:</p><table tabindex="0"><thead><tr><th></th><th>Internet</th><th>WWW</th></tr></thead><tbody><tr><td><strong>Là gì</strong></td><td>Hạ tầng – mạng vật lý toàn cầu</td><td>Dịch vụ – hệ thống trang web</td></tr><tr><td><strong>Ví dụ</strong></td><td>Đường cao tốc</td><td>Xe ô tô chạy trên đường</td></tr><tr><td><strong>Không có thì sao</strong></td><td>Không có gì hoạt động</td><td>Web không dùng được, nhưng email, game online vẫn dùng được</td></tr><tr><td><strong>Giao thức</strong></td><td>TCP/IP</td><td>HTTP/HTTPS</td></tr><tr><td><strong>Ra đời</strong></td><td>1969 (ARPANET)</td><td>1991 (Tim Berners-Lee)</td></tr></tbody></table><blockquote><p><strong>Kết luận:</strong> WWW chạy <strong>trên</strong> Internet. Internet tồn tại trước WWW 20 năm.</p></blockquote><h3 id="tai-sao-https-quan-trong" tabindex="-1">Tại sao HTTPS quan trọng? <a class="header-anchor" href="#tai-sao-https-quan-trong" aria-label="Permalink to &quot;Tại sao HTTPS quan trọng?&quot;">​</a></h3><p>Khi bạn đăng nhập ngân hàng qua HTTP (không mã hóa):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bạn gửi: username=nguyenvana&amp;password=123456</span></span>
<span class="line"><span>Kẻ tấn công (nghe lén): nhìn thấy y chang → đánh cắp được!</span></span></code></pre></div><p>Khi dùng HTTPS (mã hóa TLS):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bạn gửi: Xd3#kL9@qW7!mN2...  (đã mã hóa)</span></span>
<span class="line"><span>Kẻ tấn công: nhìn thấy chuỗi vô nghĩa → không đọc được gì!</span></span></code></pre></div><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="luong-gui-email-hoan-chinh" tabindex="-1">Luồng gửi email hoàn chỉnh <a class="header-anchor" href="#luong-gui-email-hoan-chinh" aria-label="Permalink to &quot;Luồng gửi email hoàn chỉnh&quot;">​</a></h3><p><strong>Tình huống:</strong> Bạn (dùng Gmail) gửi email cho bạn bè (dùng Outlook/Hotmail).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Bước 1] Bạn soạn email và nhấn &quot;Gửi&quot; trong Gmail (trình duyệt/app)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 2] Gmail dùng SMTP gửi email đến máy chủ SMTP của Google</span></span>
<span class="line"><span>         (smtp.gmail.com : cổng 587)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 3] Máy chủ Google → tra DNS để tìm IP máy chủ của Outlook</span></span>
<span class="line"><span>         (MX record của hotmail.com / outlook.com)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 4] Máy chủ Google → kết nối SMTP → gửi email đến máy chủ Microsoft</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 5] Email được lưu trên máy chủ Microsoft</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 6] Khi bạn bè mở Outlook:</span></span>
<span class="line"><span>         - Nếu dùng IMAP: Đồng bộ, xem trên nhiều thiết bị</span></span>
<span class="line"><span>         - Nếu dùng POP3: Tải về máy và xóa khỏi server</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 7] Bạn bè đọc được email của bạn</span></span></code></pre></div><h3 id="luong-truy-cap-trang-web" tabindex="-1">Luồng truy cập trang web <a class="header-anchor" href="#luong-truy-cap-trang-web" aria-label="Permalink to &quot;Luồng truy cập trang web&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Bước 1] Bạn gõ https://vnexpress.net vào trình duyệt</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 2] Trình duyệt hỏi DNS server: &quot;IP của vnexpress.net là gì?&quot;</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 3] DNS trả lời: &quot;203.162.0.130&quot;</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 4] Trình duyệt kết nối TCP đến 203.162.0.130, cổng 443 (HTTPS)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 5] SSL/TLS handshake – thiết lập kênh mã hóa</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 6] Trình duyệt gửi HTTP GET request: &quot;Cho tôi trang chủ&quot;</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 7] Máy chủ trả về HTML, CSS, JavaScript, hình ảnh...</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 8] Trình duyệt render và hiển thị trang web</span></span></code></pre></div><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-phan-tich-url" tabindex="-1">Ví dụ 1 – Phân tích URL <a class="header-anchor" href="#vi-du-1-–-phan-tich-url" aria-label="Permalink to &quot;Ví dụ 1 – Phân tích URL&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://www.youtube.com/watch?v=dQw4w9WgXcQ</span></span>
<span class="line"><span></span></span>
<span class="line"><span>https://     → Giao thức (HTTPS – có mã hóa)</span></span>
<span class="line"><span>www          → Subdomain (tên miền phụ)</span></span>
<span class="line"><span>youtube      → Tên miền cấp 2 (Second-level domain)</span></span>
<span class="line"><span>.com         → Tên miền cấp cao (TLD)</span></span>
<span class="line"><span>/watch       → Đường dẫn (path)</span></span>
<span class="line"><span>?v=dQw4w9WgXcQ → Tham số truy vấn (query string)</span></span></code></pre></div><h3 id="vi-du-2-–-nhan-biet-giao-thuc-tu-tinh-huong" tabindex="-1">Ví dụ 2 – Nhận biết giao thức từ tình huống <a class="header-anchor" href="#vi-du-2-–-nhan-biet-giao-thuc-tu-tinh-huong" aria-label="Permalink to &quot;Ví dụ 2 – Nhận biết giao thức từ tình huống&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tình huống</th><th>Giao thức dùng</th></tr></thead><tbody><tr><td>Upload file lên hosting website</td><td>FTP/SFTP</td></tr><tr><td>Gửi email cho giáo viên</td><td>SMTP</td></tr><tr><td>Mở app Gmail trên điện thoại, email đồng bộ nhiều thiết bị</td><td>IMAP</td></tr><tr><td>Truy cập trang web ngân hàng</td><td>HTTPS</td></tr><tr><td>Xem video trên YouTube</td><td>HTTPS (HTTP/2)</td></tr><tr><td>Tra địa chỉ IP của facebook.com</td><td>DNS</td></tr></tbody></table><h3 id="vi-du-3-–-so-sanh-pop3-vs-imap-trong-thuc-te" tabindex="-1">Ví dụ 3 – So sánh POP3 vs IMAP trong thực tế <a class="header-anchor" href="#vi-du-3-–-so-sanh-pop3-vs-imap-trong-thuc-te" aria-label="Permalink to &quot;Ví dụ 3 – So sánh POP3 vs IMAP trong thực tế&quot;">​</a></h3><p><strong>Tình huống:</strong> Bạn dùng email cả trên điện thoại và máy tính.</p><ul><li><strong>Dùng POP3:</strong> Đọc email trên máy tính → email bị tải về máy tính, <strong>không còn trên server</strong> → mở điện thoại → <strong>không thấy email đó nữa</strong>. ❌</li><li><strong>Dùng IMAP:</strong> Đọc email trên máy tính → email vẫn trên server → mở điện thoại → <strong>vẫn thấy</strong> (đã được đánh dấu đã đọc). ✅</li></ul><blockquote><p>Đây là lý do tại sao Gmail và các dịch vụ email hiện đại đều dùng <strong>IMAP</strong> mặc định.</p></blockquote><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="cac-giao-thuc-email" tabindex="-1">Các giao thức email <a class="header-anchor" href="#cac-giao-thuc-email" aria-label="Permalink to &quot;Các giao thức email&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>SMTP</th><th>POP3</th><th>IMAP</th></tr></thead><tbody><tr><td><strong>Chức năng</strong></td><td>Gửi email</td><td>Nhận email</td><td>Nhận email</td></tr><tr><td><strong>Cổng</strong></td><td>25 / 587</td><td>110 / 995</td><td>143 / 993</td></tr><tr><td><strong>Lưu trên server</strong></td><td>Không áp dụng</td><td>Xóa sau khi tải</td><td>Giữ nguyên</td></tr><tr><td><strong>Nhiều thiết bị</strong></td><td>Không áp dụng</td><td>Không</td><td>Có</td></tr><tr><td><strong>Phù hợp với</strong></td><td>Gửi đi</td><td>1 thiết bị, tiết kiệm dung lượng server</td><td>Nhiều thiết bị</td></tr></tbody></table><h3 id="http-vs-https" tabindex="-1">HTTP vs HTTPS <a class="header-anchor" href="#http-vs-https" aria-label="Permalink to &quot;HTTP vs HTTPS&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>HTTP</th><th>HTTPS</th></tr></thead><tbody><tr><td><strong>Bảo mật</strong></td><td>Không mã hóa</td><td>Mã hóa SSL/TLS</td></tr><tr><td><strong>Cổng</strong></td><td>80</td><td>443</td></tr><tr><td><strong>Tốc độ</strong></td><td>Nhanh hơn</td><td>Chậm hơn một chút (overhead mã hóa)</td></tr><tr><td><strong>SEO</strong></td><td>Điểm thấp hơn</td><td>Google ưu tiên</td></tr><tr><td><strong>Bắt buộc</strong></td><td>Không</td><td>Có (trình duyệt cảnh báo HTTP)</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>🌐 <strong>Internet</strong> = mạng của các mạng toàn cầu, dùng TCP/IP</li><li>🕸️ <strong>WWW</strong> = dịch vụ trang web chạy trên Internet, dùng HTTP/HTTPS – <strong>không phải Internet</strong></li><li>📧 <strong>SMTP</strong> = <strong>gửi</strong> email (cổng 25/587)</li><li>📥 <strong>POP3</strong> = <strong>nhận</strong> email, tải về xóa server (cổng 110/995)</li><li>📲 <strong>IMAP</strong> = <strong>nhận</strong> email, đồng bộ nhiều thiết bị (cổng 143/993)</li><li>📁 <strong>FTP</strong> = truyền file (cổng 21)</li><li>🔍 <strong>DNS</strong> = dịch tên miền → địa chỉ IP (&quot;danh bạ Internet&quot;)</li><li>🔒 <strong>HTTPS</strong> = HTTP + mã hóa SSL/TLS (cổng 443) → <strong>bảo mật</strong></li><li>🔓 <strong>HTTP</strong> = không mã hóa (cổng 80) → <strong>không bảo mật</strong></li><li>🏷️ <strong>TLD</strong>: <code>.com</code> (thương mại), <code>.edu</code> (giáo dục), <code>.gov</code> (chính phủ), <code>.vn</code> (Việt Nam)</li><li>📮 Cấu trúc email: <code>tên@nhàcungcấp.tld</code> (ví dụ: <code>nguyenvana@gmail.com</code>)</li><li>🔁 Thứ tự tra web: Gõ URL → DNS phân giải → kết nối IP → HTTPS → hiển thị trang</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-đung-hay-sai" tabindex="-1">Câu 1 (Dễ): Đúng hay Sai? <a class="header-anchor" href="#cau-1-de-đung-hay-sai" aria-label="Permalink to &quot;Câu 1 (Dễ): Đúng hay Sai?&quot;">​</a></h3><blockquote><p>&quot;Internet và World Wide Web là hai khái niệm giống nhau, có thể dùng thay thế cho nhau.&quot;</p></blockquote><p><strong>Đáp án: SAI</strong></p><p><strong>Giải thích:</strong> Internet là hạ tầng mạng vật lý toàn cầu (kết nối các máy tính). WWW là <strong>một dịch vụ</strong> chạy trên Internet (hệ thống trang web dùng HTTP/HTTPS). Internet ra đời năm 1969, WWW ra đời năm 1991. Email, FTP, game online cũng chạy trên Internet nhưng không phải WWW.</p><hr><h3 id="cau-2-de-chon-giao-thuc-phu-hop" tabindex="-1">Câu 2 (Dễ): Chọn giao thức phù hợp <a class="header-anchor" href="#cau-2-de-chon-giao-thuc-phu-hop" aria-label="Permalink to &quot;Câu 2 (Dễ): Chọn giao thức phù hợp&quot;">​</a></h3><blockquote><p>Bạn cần gửi file báo cáo lớn (500MB) lên máy chủ hosting. Bạn nên dùng giao thức nào? A. HTTP B. SMTP C. FTP D. DNS</p></blockquote><p><strong>Đáp án: C – FTP</strong></p><p><strong>Giải thích:</strong> FTP (File Transfer Protocol) được thiết kế đặc biệt để <strong>truyền file</strong> giữa máy tính và máy chủ. HTTP dùng để truy cập trang web. SMTP dùng để gửi email (không phù hợp cho file 500MB). DNS chỉ phân giải tên miền.</p><hr><h3 id="cau-3-trung-binh-phan-tich-url" tabindex="-1">Câu 3 (Trung bình): Phân tích URL <a class="header-anchor" href="#cau-3-trung-binh-phan-tich-url" aria-label="Permalink to &quot;Câu 3 (Trung bình): Phân tích URL&quot;">​</a></h3><blockquote><p>Phân tích các thành phần của URL sau: <code>https://hocsinh.edu.vn/tai-lieu/tin-hoc-12?page=3</code></p></blockquote><p><strong>Đáp án:</strong></p><table tabindex="0"><thead><tr><th>Thành phần</th><th>Giá trị</th><th>Ý nghĩa</th></tr></thead><tbody><tr><td>Giao thức</td><td><code>https</code></td><td>HTTP có mã hóa SSL/TLS</td></tr><tr><td>Tên miền</td><td><code>hocsinh.edu.vn</code></td><td>Tên miền giáo dục Việt Nam</td></tr><tr><td>TLD</td><td><code>.vn</code></td><td>Country code Việt Nam</td></tr><tr><td>SLD</td><td><code>.edu</code></td><td>Giáo dục (second level)</td></tr><tr><td>Đường dẫn</td><td><code>/tai-lieu/tin-hoc-12</code></td><td>Thư mục/trang trên server</td></tr><tr><td>Tham số</td><td><code>?page=3</code></td><td>Tham số truy vấn: trang số 3</td></tr></tbody></table><hr><h3 id="cau-4-trung-binh-chon-pop3-hay-imap" tabindex="-1">Câu 4 (Trung bình): Chọn POP3 hay IMAP <a class="header-anchor" href="#cau-4-trung-binh-chon-pop3-hay-imap" aria-label="Permalink to &quot;Câu 4 (Trung bình): Chọn POP3 hay IMAP&quot;">​</a></h3><blockquote><p>Bạn muốn kiểm tra email công việc trên cả điện thoại, máy tính văn phòng, và máy tính xách tay ở nhà. Email cần đồng bộ ở mọi nơi. Bạn nên cấu hình POP3 hay IMAP? Tại sao?</p></blockquote><p><strong>Đáp án: IMAP</strong></p><p><strong>Giải thích:</strong> IMAP giữ email trên server và đồng bộ với tất cả thiết bị. Khi bạn đọc/xóa email trên điện thoại, thay đổi đó phản ánh ngay trên máy tính văn phòng và máy tính ở nhà. POP3 sẽ tải email xuống một thiết bị và xóa khỏi server, khiến các thiết bị khác không nhìn thấy email đó.</p><hr><h3 id="cau-5-van-dung-phan-tich-bao-mat" tabindex="-1">Câu 5 (Vận dụng): Phân tích bảo mật <a class="header-anchor" href="#cau-5-van-dung-phan-tich-bao-mat" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Phân tích bảo mật&quot;">​</a></h3><blockquote><p>Bạn đang dùng Wi-Fi công cộng tại quán cà phê và truy cập trang web ngân hàng. Trang web đó dùng HTTP (không phải HTTPS). Điều gì có thể xảy ra? Bạn nên làm gì?</p></blockquote><p><strong>Đáp án:</strong></p><p><strong>Rủi ro:</strong> Kẻ tấn công có thể dùng kỹ thuật &quot;Man-in-the-Middle&quot; (nghe lén mạng Wi-Fi) để đọc được <strong>tất cả dữ liệu</strong> bạn gửi qua HTTP, bao gồm:</p><ul><li>Tên đăng nhập và mật khẩu</li><li>Số tài khoản ngân hàng</li><li>Mã OTP (nếu truyền qua HTTP)</li></ul><p><strong>Giải pháp:</strong></p><ol><li><strong>Không truy cập</strong> trang web ngân hàng nếu dùng HTTP trên Wi-Fi công cộng.</li><li>Kiểm tra xem URL có bắt đầu bằng <code>https://</code> và có biểu tượng 🔒 không.</li><li>Dùng <strong>mạng di động (4G/5G)</strong> thay vì Wi-Fi công cộng cho giao dịch nhạy cảm.</li><li>Dùng <strong>VPN</strong> để mã hóa thêm một lớp khi dùng Wi-Fi công cộng.</li></ol><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><h3 id="❌-loi-1-nham-internet-voi-www" tabindex="-1">❌ Lỗi 1: Nhầm Internet với WWW <a class="header-anchor" href="#❌-loi-1-nham-internet-voi-www" aria-label="Permalink to &quot;❌ Lỗi 1: Nhầm Internet với WWW&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Internet là hệ thống trang web toàn cầu.&quot;</p><p><strong>Đúng:</strong> <strong>WWW</strong> (World Wide Web) mới là hệ thống trang web. <strong>Internet</strong> là hạ tầng mạng vật lý kết nối máy tính toàn cầu. WWW chỉ là một trong nhiều dịch vụ chạy trên Internet (cùng với email, FTP, game online...).</p><hr><h3 id="❌-loi-2-nham-smtp-voi-pop3-imap" tabindex="-1">❌ Lỗi 2: Nhầm SMTP với POP3/IMAP <a class="header-anchor" href="#❌-loi-2-nham-smtp-voi-pop3-imap" aria-label="Permalink to &quot;❌ Lỗi 2: Nhầm SMTP với POP3/IMAP&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tôi dùng SMTP để nhận email.&quot;</p><p><strong>Đúng:</strong> <strong>SMTP chỉ dùng để GỬI email</strong>. Để nhận email, dùng <strong>POP3</strong> (tải về, xóa server) hoặc <strong>IMAP</strong> (đồng bộ nhiều thiết bị).</p><hr><h3 id="❌-loi-3-nghi-ten-mien-va-đia-chi-ip-la-mot" tabindex="-1">❌ Lỗi 3: Nghĩ tên miền và địa chỉ IP là một <a class="header-anchor" href="#❌-loi-3-nghi-ten-mien-va-đia-chi-ip-la-mot" aria-label="Permalink to &quot;❌ Lỗi 3: Nghĩ tên miền và địa chỉ IP là một&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Địa chỉ web của Google là google.com – đó cũng là địa chỉ IP của Google.&quot;</p><p><strong>Đúng:</strong> <code>google.com</code> là <strong>tên miền</strong> – dễ nhớ cho con người. <strong>Địa chỉ IP</strong> của Google là <code>142.250.196.46</code> (hoặc nhiều IP khác). <strong>DNS</strong> làm nhiệm vụ dịch tên miền sang IP khi bạn truy cập web.</p><hr><h3 id="❌-loi-4-nghi-http-va-https-chi-khac-nhau-ve-bao-mat-khong-khac-cong" tabindex="-1">❌ Lỗi 4: Nghĩ HTTP và HTTPS chỉ khác nhau về bảo mật, không khác cổng <a class="header-anchor" href="#❌-loi-4-nghi-http-va-https-chi-khac-nhau-ve-bao-mat-khong-khac-cong" aria-label="Permalink to &quot;❌ Lỗi 4: Nghĩ HTTP và HTTPS chỉ khác nhau về bảo mật, không khác cổng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;HTTP và HTTPS dùng cùng cổng 80.&quot;</p><p><strong>Đúng:</strong> HTTP dùng <strong>cổng 80</strong>, HTTPS dùng <strong>cổng 443</strong>. Đây là hai cổng khác nhau. Máy chủ web phải mở đúng cổng để nhận kết nối từ trình duyệt.</p><hr><h3 id="❌-loi-5-nham-tld-edu-vn-va-com" tabindex="-1">❌ Lỗi 5: Nhầm TLD .edu.vn và .com <a class="header-anchor" href="#❌-loi-5-nham-tld-edu-vn-va-com" aria-label="Permalink to &quot;❌ Lỗi 5: Nhầm TLD .edu.vn và .com&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Website trường học Việt Nam phải dùng tên miền .edu&quot;</p><p><strong>Đúng:</strong> Ở Việt Nam, website trường học và tổ chức giáo dục dùng tên miền <strong>.edu.vn</strong> (ví dụ: <code>hust.edu.vn</code>, <code>neu.edu.vn</code>). Đây là tên miền quốc gia cấp 2 của Việt Nam. Tên miền <code>.edu</code> (không có <code>.vn</code>) dành cho các tổ chức giáo dục của Mỹ (như <code>harvard.edu</code>).</p><hr><h3 id="❌-loi-6-nghi-url-va-uri-la-nhu-nhau" tabindex="-1">❌ Lỗi 6: Nghĩ URL và URI là như nhau <a class="header-anchor" href="#❌-loi-6-nghi-url-va-uri-la-nhu-nhau" aria-label="Permalink to &quot;❌ Lỗi 6: Nghĩ URL và URI là như nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;URL và URI đều là địa chỉ web, như nhau.&quot;</p><p><strong>Đúng:</strong> <strong>URI (Uniform Resource Identifier)</strong> là định danh tổng quát cho tài nguyên. <strong>URL (Uniform Resource Locator)</strong> là loại URI cụ thể, bao gồm cả giao thức và địa chỉ. Mọi URL đều là URI, nhưng không phải URI nào cũng là URL (ví dụ: URN như <code>urn:isbn:978-3-16-148410-0</code> là URI nhưng không phải URL).</p><hr><h3 id="❌-loi-7-nham-browser-voi-web-server" tabindex="-1">❌ Lỗi 7: Nhầm browser với web server <a class="header-anchor" href="#❌-loi-7-nham-browser-voi-web-server" aria-label="Permalink to &quot;❌ Lỗi 7: Nhầm browser với web server&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Chrome là web server, nó tải và chạy website.&quot;</p><p><strong>Đúng:</strong> <strong>Browser (Chrome, Firefox)</strong> là <strong>web client</strong> – gửi HTTP request đến server và hiển thị kết quả. <strong>Web server (Apache, Nginx, IIS)</strong> nhận request, xử lý, và trả về HTML/CSS/JS. Không có web server, browser không có gì để hiển thị.</p><hr><h3 id="❌-loi-8-nghi-dns-chi-dich-domain-sang-ipv4" tabindex="-1">❌ Lỗi 8: Nghĩ DNS chỉ dịch domain sang IPv4 <a class="header-anchor" href="#❌-loi-8-nghi-dns-chi-dich-domain-sang-ipv4" aria-label="Permalink to &quot;❌ Lỗi 8: Nghĩ DNS chỉ dịch domain sang IPv4&quot;">​</a></h3><p><strong>Sai:</strong> &quot;DNS chỉ dịch tên website thành địa chỉ IPv4.&quot;</p><p><strong>Đúng:</strong> DNS có nhiều loại record: <strong>A</strong> (domain → IPv4), <strong>AAAA</strong> (domain → IPv6), <strong>MX</strong> (domain → mail server), <strong>CNAME</strong> (alias), <strong>TXT</strong> (thông tin text, dùng cho SPF/DKIM), <strong>NS</strong> (name server), <strong>PTR</strong> (reverse lookup: IP → domain). DNS là hệ thống toàn diện hơn chỉ dịch tên.</p><hr><h3 id="❌-loi-9-nham-đe-quy-dns-voi-iterative-dns" tabindex="-1">❌ Lỗi 9: Nhầm đệ quy DNS với iterative DNS <a class="header-anchor" href="#❌-loi-9-nham-đe-quy-dns-voi-iterative-dns" aria-label="Permalink to &quot;❌ Lỗi 9: Nhầm đệ quy DNS với iterative DNS&quot;">​</a></h3><p><strong>Sai:</strong> &quot;DNS server luôn trả lời trực tiếp câu hỏi của client.&quot;</p><p><strong>Đúng:</strong> <strong>Recursive DNS</strong> (server làm hết việc thay client): client hỏi DNS resolver → resolver hỏi root → hỏi TLD → hỏi authoritative → trả kết quả cho client. <strong>Iterative DNS</strong>: client phải tự hỏi từng bước. Các DNS resolver của ISP (8.8.8.8, 1.1.1.1) dùng recursive lookup.</p><hr><h3 id="❌-loi-10-nghi-port-25-va-port-587-đeu-dung-đe-gui-email-nhu-nhau" tabindex="-1">❌ Lỗi 10: Nghĩ port 25 và port 587 đều dùng để gửi email như nhau <a class="header-anchor" href="#❌-loi-10-nghi-port-25-va-port-587-đeu-dung-đe-gui-email-nhu-nhau" aria-label="Permalink to &quot;❌ Lỗi 10: Nghĩ port 25 và port 587 đều dùng để gửi email như nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Port 25 và 587 đều dùng SMTP, như nhau.&quot;</p><p><strong>Đúng:</strong> <strong>Port 25</strong> là SMTP giữa các <strong>mail server</strong> (server-to-server). <strong>Port 587</strong> là SMTP <strong>submission</strong> – dùng cho email client (Outlook, Gmail app) gửi email đến mail server, với yêu cầu authentication bắt buộc. Nhiều ISP chặn port 25 từ IP khách hàng để ngăn spam.</p><hr><h3 id="❌-loi-11-nham-hosting-voi-domain-name" tabindex="-1">❌ Lỗi 11: Nhầm hosting với domain name <a class="header-anchor" href="#❌-loi-11-nham-hosting-voi-domain-name" aria-label="Permalink to &quot;❌ Lỗi 11: Nhầm hosting với domain name&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mua tên miền (domain) là đủ để có website.&quot;</p><p><strong>Đúng:</strong> Cần hai thứ riêng biệt: <strong>domain name</strong> (như <code>truong.edu.vn</code>) – thuê tại nhà đăng ký tên miền (registrar). <strong>Hosting</strong> – máy chủ lưu và chạy các file website. Sau khi có cả hai, cần trỏ DNS của domain về IP của hosting. Thiếu một trong hai thì website không hoạt động.</p><hr><h3 id="❌-loi-12-nghi-imap-xoa-email-khoi-server" tabindex="-1">❌ Lỗi 12: Nghĩ IMAP xóa email khỏi server <a class="header-anchor" href="#❌-loi-12-nghi-imap-xoa-email-khoi-server" aria-label="Permalink to &quot;❌ Lỗi 12: Nghĩ IMAP xóa email khỏi server&quot;">​</a></h3><p><strong>Sai:</strong> &quot;IMAP tải email về máy rồi xóa khỏi server như POP3.&quot;</p><p><strong>Đúng:</strong> <strong>IMAP</strong> đồng bộ email với server – email vẫn lưu trên server, client hiển thị bản sao đồng bộ. Xóa trên máy này sẽ xóa trên server và đồng bộ tới máy khác. <strong>POP3</strong> mới tải về và (tùy cấu hình) xóa khỏi server. IMAP phù hợp dùng nhiều thiết bị, POP3 phù hợp lưu offline.</p><hr><h3 id="❌-loi-13-nham-vpn-voi-proxy" tabindex="-1">❌ Lỗi 13: Nhầm VPN với proxy <a class="header-anchor" href="#❌-loi-13-nham-vpn-voi-proxy" aria-label="Permalink to &quot;❌ Lỗi 13: Nhầm VPN với proxy&quot;">​</a></h3><p><strong>Sai:</strong> &quot;VPN và proxy đều ẩn địa chỉ IP, như nhau.&quot;</p><p><strong>Đúng:</strong> <strong>Proxy</strong> ẩn IP cho một ứng dụng cụ thể (như browser), hoạt động ở Tầng 7. <strong>VPN</strong> mã hóa toàn bộ lưu lượng mạng của hệ thống (tất cả ứng dụng), hoạt động ở Tầng 3-4. VPN bảo mật hơn và toàn diện hơn proxy. Một số proxy không mã hóa, chỉ ẩn IP.</p><hr><h3 id="❌-loi-14-nghi-vn-chi-danh-cho-website-tai-viet-nam" tabindex="-1">❌ Lỗi 14: Nghĩ .vn chỉ dành cho website tại Việt Nam <a class="header-anchor" href="#❌-loi-14-nghi-vn-chi-danh-cho-website-tai-viet-nam" aria-label="Permalink to &quot;❌ Lỗi 14: Nghĩ .vn chỉ dành cho website tại Việt Nam&quot;">​</a></h3><p><strong>Sai:</strong> &quot;.vn là TLD (Top-Level Domain) chỉ cho người dùng ở Việt Nam.&quot;</p><p><strong>Đúng:</strong> <strong>.vn</strong> là <strong>ccTLD (country-code TLD)</strong> của Việt Nam và được quản lý bởi VNNIC. Tuy nhiên, bất kỳ tổ chức nào ở Việt Nam (không nhất thiết phải là người dùng) có thể đăng ký <code>.vn</code>. Tương tự, website dùng <code>.vn</code> có thể được truy cập từ bất kỳ đâu trên thế giới.</p><hr><h3 id="❌-loi-15-nghi-cdn-la-mot-server-lon-đat-o-trung-tam" tabindex="-1">❌ Lỗi 15: Nghĩ CDN là một server lớn đặt ở trung tâm <a class="header-anchor" href="#❌-loi-15-nghi-cdn-la-mot-server-lon-đat-o-trung-tam" aria-label="Permalink to &quot;❌ Lỗi 15: Nghĩ CDN là một server lớn đặt ở trung tâm&quot;">​</a></h3><p><strong>Sai:</strong> &quot;CDN là một server rất lớn và mạnh để phục vụ nhiều người dùng.&quot;</p><p><strong>Đúng:</strong> <strong>CDN (Content Delivery Network)</strong> là mạng lưới nhiều server (Point of Presence – PoP) phân tán toàn cầu. Khi bạn tải ảnh từ Facebook, file được phục vụ từ <strong>server CDN gần bạn nhất</strong> (ở Singapore hoặc Hong Kong thay vì từ Mỹ). CDN giảm latency và tải cho server gốc.</p><hr><h3 id="❌-loi-16-nham-http-request-va-http-response" tabindex="-1">❌ Lỗi 16: Nhầm HTTP request và HTTP response <a class="header-anchor" href="#❌-loi-16-nham-http-request-va-http-response" aria-label="Permalink to &quot;❌ Lỗi 16: Nhầm HTTP request và HTTP response&quot;">​</a></h3><p><strong>Sai:</strong> &quot;HTTP request là thông tin máy chủ gửi cho trình duyệt.&quot;</p><p><strong>Đúng:</strong> <strong>HTTP request</strong> là thông tin <strong>trình duyệt (client) GỬI đến server</strong> – chứa method (GET, POST), URL, headers, và đôi khi body. <strong>HTTP response</strong> là <strong>server phản hồi về</strong> – chứa status code (200, 404, 500...), headers, và body (HTML, JSON...).</p><hr><h3 id="❌-loi-17-nghi-http-get-va-post-chi-khac-cach-truyen-du-lieu" tabindex="-1">❌ Lỗi 17: Nghĩ HTTP GET và POST chỉ khác cách truyền dữ liệu <a class="header-anchor" href="#❌-loi-17-nghi-http-get-va-post-chi-khac-cach-truyen-du-lieu" aria-label="Permalink to &quot;❌ Lỗi 17: Nghĩ HTTP GET và POST chỉ khác cách truyền dữ liệu&quot;">​</a></h3><p><strong>Sai:</strong> &quot;GET và POST chỉ khác nhau là GET đặt dữ liệu trên URL, POST đặt trong body.&quot;</p><p><strong>Đúng:</strong> Khác biệt quan trọng hơn: <strong>GET</strong> là safe và idempotent – không thay đổi dữ liệu server, có thể cache, bookmark được. <strong>POST</strong> thay đổi trạng thái server (tạo dữ liệu mới), không cache được theo mặc định, không bookmark được. Dùng sai method có thể gây lỗi logic hoặc bảo mật.</p><hr><h3 id="❌-loi-18-nham-http-status-code-301-va-302" tabindex="-1">❌ Lỗi 18: Nhầm HTTP status code 301 và 302 <a class="header-anchor" href="#❌-loi-18-nham-http-status-code-301-va-302" aria-label="Permalink to &quot;❌ Lỗi 18: Nhầm HTTP status code 301 và 302&quot;">​</a></h3><p><strong>Sai:</strong> &quot;301 và 302 đều redirect, dùng cái nào cũng được.&quot;</p><p><strong>Đúng:</strong> <strong>301 Moved Permanently</strong> – URL thay đổi vĩnh viễn, browser cache redirect này, SEO truyền &quot;link juice&quot;. <strong>302 Found (Temporary Redirect)</strong> – redirect tạm thời, browser không cache. Dùng sai: dùng 302 khi nên dùng 301 → SEO bị ảnh hưởng; dùng 301 khi nên dùng 302 → redirect tạm thời bị cache nhầm.</p><hr><h3 id="❌-loi-19-nghi-https-khong-the-bi-tan-cong-man-in-the-middle" tabindex="-1">❌ Lỗi 19: Nghĩ HTTPS không thể bị tấn công Man-in-the-Middle <a class="header-anchor" href="#❌-loi-19-nghi-https-khong-the-bi-tan-cong-man-in-the-middle" aria-label="Permalink to &quot;❌ Lỗi 19: Nghĩ HTTPS không thể bị tấn công Man-in-the-Middle&quot;">​</a></h3><p><strong>Sai:</strong> &quot;HTTPS mã hóa 100%, không thể bị nghe lén hay tấn công.&quot;</p><p><strong>Đúng:</strong> HTTPS <strong>có thể bị tấn công MITM</strong> nếu: certificate không được xác thực đúng (certificate pinning), người dùng chấp nhận certificate giả, hoặc CA (Certificate Authority) bị compromise. Công ty thường dùng SSL inspection (corporate MITM) để giám sát lưu lượng HTTPS của nhân viên.</p><hr><h3 id="❌-loi-20-nham-dns-cache-va-browser-cache" tabindex="-1">❌ Lỗi 20: Nhầm DNS cache và browser cache <a class="header-anchor" href="#❌-loi-20-nham-dns-cache-va-browser-cache" aria-label="Permalink to &quot;❌ Lỗi 20: Nhầm DNS cache và browser cache&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Xóa cache trình duyệt là xóa hết cache DNS.&quot;</p><p><strong>Đúng:</strong> <strong>Browser cache</strong> lưu website files (HTML, CSS, JS, ảnh). <strong>DNS cache</strong> lưu ánh xạ domain → IP. Chúng ở hai nơi khác nhau: browser cache trong thư mục trình duyệt, DNS cache trong hệ điều hành (xóa bằng <code>ipconfig /flushdns</code> trên Windows). Xóa browser cache không ảnh hưởng DNS cache.</p><hr><h3 id="❌-loi-21-nghi-google-com-va-www-google-com-la-y-het-nhau" tabindex="-1">❌ Lỗi 21: Nghĩ Google.com và www.google.com là y hệt nhau <a class="header-anchor" href="#❌-loi-21-nghi-google-com-va-www-google-com-la-y-het-nhau" aria-label="Permalink to &quot;❌ Lỗi 21: Nghĩ Google.com và www.google.com là y hệt nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;google.com và www.google.com là cùng một thứ, không có sự khác biệt.&quot;</p><p><strong>Đúng:</strong> Về mặt kỹ thuật, <code>google.com</code> (apex domain) và <code>www.google.com</code> (subdomain) là <strong>hai domain khác nhau</strong>. Google đã cấu hình redirect từ cái này sang cái kia. Một số website không cấu hình này – truy cập một trong hai có thể không hoạt động. DNS A record và CNAME record cũng khác nhau giữa apex và subdomain.</p><hr><h3 id="❌-loi-22-nham-web-hosting-shared-va-vps" tabindex="-1">❌ Lỗi 22: Nhầm web hosting shared và VPS <a class="header-anchor" href="#❌-loi-22-nham-web-hosting-shared-va-vps" aria-label="Permalink to &quot;❌ Lỗi 22: Nhầm web hosting shared và VPS&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Shared hosting và VPS đều là thuê máy chủ, giống nhau.&quot;</p><p><strong>Đúng:</strong> <strong>Shared hosting</strong>: nhiều website dùng chung một máy chủ vật lý, tài nguyên chia sẻ, giá rẻ, hạn chế tùy chỉnh. <strong>VPS (Virtual Private Server)</strong>: máy ảo riêng biệt trên server vật lý, tài nguyên cam kết riêng, toàn quyền cấu hình, giá cao hơn. VPS phù hợp cho ứng dụng cần hiệu năng và tùy chỉnh cao.</p><hr><h3 id="❌-loi-23-nghi-ftp-an-toan-hon-http" tabindex="-1">❌ Lỗi 23: Nghĩ FTP an toàn hơn HTTP <a class="header-anchor" href="#❌-loi-23-nghi-ftp-an-toan-hon-http" aria-label="Permalink to &quot;❌ Lỗi 23: Nghĩ FTP an toàn hơn HTTP&quot;">​</a></h3><p><strong>Sai:</strong> &quot;FTP an toàn hơn HTTP vì cần đăng nhập.&quot;</p><p><strong>Đúng:</strong> FTP truyền dữ liệu <strong>không mã hóa</strong> – username, password, và dữ liệu đều có thể bị nghe lén. HTTP cũng không mã hóa, nhưng không phải vì vậy mà FTP &quot;an toàn hơn&quot;. Cả hai đều kém bảo mật. Nên dùng <strong>HTTPS</strong> (thay HTTP) và <strong>SFTP/FTPS</strong> (thay FTP) trên mạng không tin cậy.</p><hr><h3 id="❌-loi-24-nham-url-shortener-voi-redirect" tabindex="-1">❌ Lỗi 24: Nhầm URL shortener với redirect <a class="header-anchor" href="#❌-loi-24-nham-url-shortener-voi-redirect" aria-label="Permalink to &quot;❌ Lỗi 24: Nhầm URL shortener với redirect&quot;">​</a></h3><p><strong>Sai:</strong> &quot;URL rút gọn (bit.ly) thay đổi địa chỉ thật của website.&quot;</p><p><strong>Đúng:</strong> URL shortener chỉ tạo <strong>redirect</strong>: khi bạn click <code>bit.ly/abc</code>, server của bit.ly trả về HTTP 301/302 redirect đến URL thật. Địa chỉ website thật không thay đổi. Nhược điểm bảo mật: không biết URL thật dẫn đến đâu trước khi click – link rút gọn có thể che giấu link độc hại.</p><hr><h3 id="❌-loi-25-nghi-cookies-la-file-nguy-hiem" tabindex="-1">❌ Lỗi 25: Nghĩ cookies là file nguy hiểm <a class="header-anchor" href="#❌-loi-25-nghi-cookies-la-file-nguy-hiem" aria-label="Permalink to &quot;❌ Lỗi 25: Nghĩ cookies là file nguy hiểm&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Cookies lưu thông tin bí mật và là mối đe dọa bảo mật lớn.&quot;</p><p><strong>Đúng:</strong> <strong>Cookies</strong> chỉ là file text nhỏ lưu trạng thái session, tùy chọn người dùng. Bản thân cookies không nguy hiểm. Vấn đề bảo mật liên quan: <strong>cookie theft</strong> (đánh cắp session cookie qua XSS), <strong>cross-site tracking</strong> (theo dõi người dùng trên nhiều website). Cookies cần thiết cho chức năng đăng nhập.</p><hr><h3 id="❌-loi-26-nham-telnet-voi-ssh-va-đieu-đo-khong-quan-trong" tabindex="-1">❌ Lỗi 26: Nhầm Telnet với SSH và điều đó không quan trọng <a class="header-anchor" href="#❌-loi-26-nham-telnet-voi-ssh-va-đieu-đo-khong-quan-trong" aria-label="Permalink to &quot;❌ Lỗi 26: Nhầm Telnet với SSH và điều đó không quan trọng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Telnet hay SSH đều điều khiển máy chủ được, dùng cái nào cũng được.&quot;</p><p><strong>Đúng:</strong> <strong>Telnet</strong> truyền không mã hóa – toàn bộ lệnh và kết quả hiển thị plaintext. <strong>SSH</strong> mã hóa toàn bộ. Dùng Telnet trên mạng không tin cậy là thảm họa bảo mật. SSH là tiêu chuẩn hiện đại, Telnet đã lỗi thời và không nên dùng.</p><hr><h3 id="❌-loi-27-nghi-domain-name-luon-phai-la-com-hoac-vn" tabindex="-1">❌ Lỗi 27: Nghĩ domain name luôn phải là .com hoặc .vn <a class="header-anchor" href="#❌-loi-27-nghi-domain-name-luon-phai-la-com-hoac-vn" aria-label="Permalink to &quot;❌ Lỗi 27: Nghĩ domain name luôn phải là .com hoặc .vn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Website hợp lệ phải dùng domain .com hoặc .edu.&quot;</p><p><strong>Đúng:</strong> Có hơn <strong>1500 TLD (Top-Level Domains)</strong> hiện nay: .com, .org, .net, .edu, .gov, ccTLD (.vn, .jp, .uk...), và gTLD mới như .shop, .app, .tech, .blog, .dev... Website hoàn toàn hợp lệ với bất kỳ TLD nào đăng ký đúng cách. Ví dụ: del.icio.us, Google.io, GitHub.dev.</p><hr><h3 id="❌-loi-28-nham-web-server-voi-application-server" tabindex="-1">❌ Lỗi 28: Nhầm web server với application server <a class="header-anchor" href="#❌-loi-28-nham-web-server-voi-application-server" aria-label="Permalink to &quot;❌ Lỗi 28: Nhầm web server với application server&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Web server (Nginx) và application server (Node.js) là một.&quot;</p><p><strong>Đúng:</strong> <strong>Web server</strong> (Nginx, Apache) phục vụ file tĩnh (HTML, CSS, ảnh) và nhận HTTP request. <strong>Application server</strong> chạy logic ứng dụng (Node.js, Django, PHP-FPM). Thường dùng cả hai: Nginx làm reverse proxy, nhận request, chuyển cho app server xử lý, lấy kết quả và trả về client.</p><hr><h3 id="❌-loi-29-nghi-ping-website-la-kiem-tra-website-đang-hoat-đong" tabindex="-1">❌ Lỗi 29: Nghĩ ping website là kiểm tra website đang hoạt động <a class="header-anchor" href="#❌-loi-29-nghi-ping-website-la-kiem-tra-website-đang-hoat-đong" aria-label="Permalink to &quot;❌ Lỗi 29: Nghĩ ping website là kiểm tra website đang hoạt động&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Ping được google.com là website đang hoạt động bình thường.&quot;</p><p><strong>Đúng:</strong> Ping kiểm tra <strong>kết nối mạng đến IP của server</strong>, không kiểm tra web service. Nhiều server <strong>chặn ICMP ping</strong> vì lý do bảo mật – ping không thành công nhưng website vẫn hoạt động. Để kiểm tra website, dùng <code>curl</code> hoặc browser để gửi HTTP request.</p><hr><h3 id="❌-loi-30-nham-tcp-port-80-voi-udp-port-80" tabindex="-1">❌ Lỗi 30: Nhầm TCP port 80 với UDP port 80 <a class="header-anchor" href="#❌-loi-30-nham-tcp-port-80-voi-udp-port-80" aria-label="Permalink to &quot;❌ Lỗi 30: Nhầm TCP port 80 với UDP port 80&quot;">​</a></h3><p><strong>Sai:</strong> &quot;HTTP dùng cổng 80, dù là TCP hay UDP.&quot;</p><p><strong>Đúng:</strong> HTTP/1.x và HTTP/2 dùng <strong>TCP port 80</strong> (hoặc TCP 443 cho HTTPS). <strong>HTTP/3 (QUIC) dùng UDP port 443</strong>. Port number và giao thức transport (TCP/UDP) là hai khái niệm riêng. Cùng số port nhưng TCP/UDP khác nhau là hai &quot;kênh&quot; khác nhau.</p><hr><h3 id="❌-loi-31-nghi-email-đuoc-gui-truc-tiep-đen-nguoi-nhan" tabindex="-1">❌ Lỗi 31: Nghĩ email được gửi trực tiếp đến người nhận <a class="header-anchor" href="#❌-loi-31-nghi-email-đuoc-gui-truc-tiep-đen-nguoi-nhan" aria-label="Permalink to &quot;❌ Lỗi 31: Nghĩ email được gửi trực tiếp đến người nhận&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Khi gửi email, email đi thẳng từ máy bạn đến hộp thư người nhận.&quot;</p><p><strong>Đúng:</strong> Email đi qua nhiều bước: client → <strong>SMTP server</strong> của bạn → <strong>DNS lookup MX record</strong> → <strong>SMTP server đích</strong> → lưu vào mailbox → người nhận dùng IMAP/POP3 lấy về. Email có thể qua nhiều relay server và mất vài phút đến vài giờ tùy tình huống.</p><hr><h3 id="❌-loi-32-nham-hashing-voi-ma-hoa-trong-luu-tru-mat-khau" tabindex="-1">❌ Lỗi 32: Nhầm hashing với mã hóa trong lưu trữ mật khẩu <a class="header-anchor" href="#❌-loi-32-nham-hashing-voi-ma-hoa-trong-luu-tru-mat-khau" aria-label="Permalink to &quot;❌ Lỗi 32: Nhầm hashing với mã hóa trong lưu trữ mật khẩu&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Website lưu mật khẩu bằng cách mã hóa (encrypt).&quot;</p><p><strong>Đúng:</strong> Website tốt lưu mật khẩu bằng <strong>hashing</strong> (bcrypt, Argon2, scrypt) – quá trình một chiều, không thể giải mã. Nếu database bị hack, hacker không lấy được mật khẩu gốc (phải brute-force hash). <strong>Không bao giờ nên lưu mật khẩu dưới dạng plaintext hoặc reversible encryption</strong>.</p><hr><h3 id="❌-loi-33-nghi-bandwidth-va-throughput-la-nhu-nhau" tabindex="-1">❌ Lỗi 33: Nghĩ bandwidth và throughput là như nhau <a class="header-anchor" href="#❌-loi-33-nghi-bandwidth-va-throughput-la-nhu-nhau" aria-label="Permalink to &quot;❌ Lỗi 33: Nghĩ bandwidth và throughput là như nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Bandwidth và throughput đều là tốc độ mạng, như nhau.&quot;</p><p><strong>Đúng:</strong> <strong>Bandwidth</strong> là dung lượng tối đa của kênh truyền (lý thuyết). <strong>Throughput</strong> là lượng dữ liệu thực sự truyền được trong thực tế, luôn nhỏ hơn bandwidth do: protocol overhead, retransmission, lỗi mạng, và chia sẻ băng thông với traffic khác.</p><hr><h3 id="❌-loi-34-nham-đia-chi-ip-cua-website-voi-đia-chi-ip-cua-nguoi-dung" tabindex="-1">❌ Lỗi 34: Nhầm địa chỉ IP của website với địa chỉ IP của người dùng <a class="header-anchor" href="#❌-loi-34-nham-đia-chi-ip-cua-website-voi-đia-chi-ip-cua-nguoi-dung" aria-label="Permalink to &quot;❌ Lỗi 34: Nhầm địa chỉ IP của website với địa chỉ IP của người dùng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Khi vào website, website biết được địa chỉ IP máy tính của tôi là địa chỉ nhà.&quot;</p><p><strong>Đúng:</strong> Website thấy <strong>IP công cộng</strong> của router nhà bạn (do NAT), không phải IP nội bộ máy tính (192.168.x.x). ISP biết chính xác hơn. Với IPv6 và static IP, có thể trace gần hơn. Nhưng IP công cộng không chỉ đến địa chỉ nhà bạn, chỉ đến khu vực/thành phố.</p><hr><h3 id="❌-loi-35-nghi-ddns-va-dns-la-hoan-toan-khac-nhau" tabindex="-1">❌ Lỗi 35: Nghĩ DDNS và DNS là hoàn toàn khác nhau <a class="header-anchor" href="#❌-loi-35-nghi-ddns-va-dns-la-hoan-toan-khac-nhau" aria-label="Permalink to &quot;❌ Lỗi 35: Nghĩ DDNS và DNS là hoàn toàn khác nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;DDNS và DNS không liên quan gì đến nhau.&quot;</p><p><strong>Đúng:</strong> <strong>DDNS (Dynamic DNS)</strong> là dịch vụ cập nhật DNS record <strong>tự động</strong> khi IP công cộng của bạn thay đổi. Hữu ích khi bạn muốn chạy server tại nhà nhưng ISP cấp IP động (thay đổi định kỳ). DDNS vẫn là DNS – chỉ thêm cơ chế cập nhật tự động.</p><hr><h3 id="❌-loi-36-nham-rest-api-voi-soap" tabindex="-1">❌ Lỗi 36: Nhầm REST API với SOAP <a class="header-anchor" href="#❌-loi-36-nham-rest-api-voi-soap" aria-label="Permalink to &quot;❌ Lỗi 36: Nhầm REST API với SOAP&quot;">​</a></h3><p><strong>Sai:</strong> &quot;REST API và SOAP đều là API, giống nhau hoàn toàn.&quot;</p><p><strong>Đúng:</strong> <strong>REST (Representational State Transfer)</strong> dùng HTTP/HTTPS, truyền dữ liệu JSON/XML, đơn giản, nhẹ, phổ biến hiện nay. <strong>SOAP (Simple Object Access Protocol)</strong> dùng XML chặt chẽ, phức tạp hơn, dùng nhiều trong hệ thống doanh nghiệp cũ. REST linh hoạt hơn, SOAP chuẩn hóa hơn và có built-in error handling.</p><hr><h3 id="❌-loi-37-nghi-website-va-web-application-la-nhu-nhau" tabindex="-1">❌ Lỗi 37: Nghĩ website và web application là như nhau <a class="header-anchor" href="#❌-loi-37-nghi-website-va-web-application-la-nhu-nhau" aria-label="Permalink to &quot;❌ Lỗi 37: Nghĩ website và web application là như nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Website và web application là tên khác nhau cho cùng một thứ.&quot;</p><p><strong>Đúng:</strong> <strong>Website</strong> thường là tập hợp trang HTML tĩnh hoặc đơn giản – như trang giới thiệu công ty. <strong>Web application</strong> là phần mềm chạy trên web – như Gmail, Google Docs – có tương tác phức tạp, xử lý logic phía server, và thao tác dữ liệu động. Ranh giới ngày càng mờ với Single Page Application (SPA).</p><hr><h3 id="❌-loi-38-nham-internet-va-intranet" tabindex="-1">❌ Lỗi 38: Nhầm Internet và Intranet <a class="header-anchor" href="#❌-loi-38-nham-internet-va-intranet" aria-label="Permalink to &quot;❌ Lỗi 38: Nhầm Internet và Intranet&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Intranet là Internet chậm hơn trong công ty.&quot;</p><p><strong>Đúng:</strong> <strong>Intranet</strong> là mạng riêng nội bộ của tổ chức, dùng công nghệ web (HTTP, HTML) nhưng chỉ truy cập được từ bên trong hoặc qua VPN – không phải Internet. Nội dung trên Intranet (tài liệu nội bộ, HR portal) không public. <strong>Extranet</strong> là phần Intranet mở cho đối tác bên ngoài.</p><hr><h3 id="❌-loi-39-nghi-tat-ca-website-đeu-dung-port-80-hoac-443" tabindex="-1">❌ Lỗi 39: Nghĩ tất cả website đều dùng port 80 hoặc 443 <a class="header-anchor" href="#❌-loi-39-nghi-tat-ca-website-đeu-dung-port-80-hoac-443" aria-label="Permalink to &quot;❌ Lỗi 39: Nghĩ tất cả website đều dùng port 80 hoặc 443&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Website luôn dùng port 80 (HTTP) hoặc 443 (HTTPS).&quot;</p><p><strong>Đúng:</strong> Port 80 và 443 là <strong>default ports</strong> – khi không ghi port trong URL thì trình duyệt dùng mặc định. Bất kỳ port nào cũng có thể chạy web server: <code>http://server:8080</code>, <code>https://server:8443</code>. Nhiều developer dùng port khác để dev/testing. Port chỉ là số quy ước.</p><hr><h3 id="❌-loi-40-nham-web-scraping-voi-hacking" tabindex="-1">❌ Lỗi 40: Nhầm web scraping với hacking <a class="header-anchor" href="#❌-loi-40-nham-web-scraping-voi-hacking" aria-label="Permalink to &quot;❌ Lỗi 40: Nhầm web scraping với hacking&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tự động tải dữ liệu từ website là hành vi hacking bất hợp pháp.&quot;</p><p><strong>Đúng:</strong> <strong>Web scraping</strong> (thu thập dữ liệu web tự động) không tự nhiên là bất hợp pháp. Tuy nhiên: vi phạm Terms of Service, tạo tải quá mức (DoS), hoặc thu thập dữ liệu cá nhân có thể vi phạm pháp luật. Nhiều website cung cấp <strong>API</strong> chính thức để truy cập dữ liệu hợp pháp.</p><hr><h3 id="❌-loi-41-nghi-ssl-certificate-va-ssl-encryption-la-mot" tabindex="-1">❌ Lỗi 41: Nghĩ SSL certificate và SSL encryption là một <a class="header-anchor" href="#❌-loi-41-nghi-ssl-certificate-va-ssl-encryption-la-mot" aria-label="Permalink to &quot;❌ Lỗi 41: Nghĩ SSL certificate và SSL encryption là một&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mua SSL certificate là đã bảo mật website.&quot;</p><p><strong>Đúng:</strong> <strong>SSL/TLS certificate</strong> xác thực danh tính server (chứng minh google.com thật sự là của Google). <strong>SSL/TLS encryption</strong> mã hóa dữ liệu trong transit. Certificate cần thiết để thiết lập mã hóa, nhưng chỉ certificate không đủ – cần cấu hình TLS đúng (ciphers mạnh, loại bỏ giao thức cũ như SSLv3, TLS 1.0).</p><hr><h3 id="❌-loi-42-nham-server-side-rendering-va-client-side-rendering" tabindex="-1">❌ Lỗi 42: Nhầm server-side rendering và client-side rendering <a class="header-anchor" href="#❌-loi-42-nham-server-side-rendering-va-client-side-rendering" aria-label="Permalink to &quot;❌ Lỗi 42: Nhầm server-side rendering và client-side rendering&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Website luôn được render (hiển thị) ở server.&quot;</p><p><strong>Đúng:</strong> <strong>Server-side rendering (SSR)</strong>: server tạo HTML hoàn chỉnh gửi về browser – load nhanh lần đầu, tốt cho SEO. <strong>Client-side rendering (CSR)</strong>: server gửi JavaScript, browser chạy JS để tạo HTML – load lần đầu chậm hơn nhưng tương tác mượt sau đó. React, Vue, Angular thường dùng CSR.</p><hr><h3 id="❌-loi-43-nghi-dns-propagation-xay-ra-ngay-lap-tuc" tabindex="-1">❌ Lỗi 43: Nghĩ DNS propagation xảy ra ngay lập tức <a class="header-anchor" href="#❌-loi-43-nghi-dns-propagation-xay-ra-ngay-lap-tuc" aria-label="Permalink to &quot;❌ Lỗi 43: Nghĩ DNS propagation xảy ra ngay lập tức&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Đổi DNS record xong là website dùng ngay địa chỉ mới.&quot;</p><p><strong>Đúng:</strong> Thay đổi DNS mất thời gian <strong>propagate</strong> (lan truyền) toàn cầu vì DNS được cache ở nhiều resolver với TTL khác nhau. Thường mất 24–48 giờ để toàn bộ thế giới thấy thay đổi. Giảm TTL xuống thấp trước khi thay đổi (vài giờ trước) giúp propagation nhanh hơn.</p><hr><h3 id="❌-loi-44-nham-load-balancer-voi-cdn" tabindex="-1">❌ Lỗi 44: Nhầm load balancer với CDN <a class="header-anchor" href="#❌-loi-44-nham-load-balancer-voi-cdn" aria-label="Permalink to &quot;❌ Lỗi 44: Nhầm load balancer với CDN&quot;">​</a></h3><p><strong>Sai:</strong> &quot;CDN và load balancer đều phân phối traffic đến nhiều server.&quot;</p><p><strong>Đúng:</strong> <strong>CDN</strong> phân phối <strong>nội dung tĩnh</strong> (ảnh, CSS, JS) đến server gần người dùng nhất để giảm latency. <strong>Load balancer</strong> phân phối <strong>request</strong> đến nhiều server backend để tăng khả năng xử lý và dự phòng. CDN giải quyết vấn đề địa lý; load balancer giải quyết vấn đề công suất.</p><hr><h3 id="❌-loi-45-nghi-http-2-yeu-cau-https" tabindex="-1">❌ Lỗi 45: Nghĩ HTTP/2 yêu cầu HTTPS <a class="header-anchor" href="#❌-loi-45-nghi-http-2-yeu-cau-https" aria-label="Permalink to &quot;❌ Lỗi 45: Nghĩ HTTP/2 yêu cầu HTTPS&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Muốn dùng HTTP/2 phải có HTTPS.&quot;</p><p><strong>Đúng:</strong> <strong>Về mặt kỹ thuật</strong>, HTTP/2 spec (RFC 7540) không bắt buộc HTTPS. Có h2c (HTTP/2 cleartext, không mã hóa). <strong>Thực tế</strong>, tất cả trình duyệt lớn (Chrome, Firefox) chỉ hỗ trợ HTTP/2 qua TLS. Vì vậy, trong thực tế web, HTTP/2 = HTTPS. Nhưng về mặt chuẩn, không bắt buộc.</p><hr><h3 id="❌-loi-46-nham-dns-over-https-doh-voi-https" tabindex="-1">❌ Lỗi 46: Nhầm DNS over HTTPS (DoH) với HTTPS <a class="header-anchor" href="#❌-loi-46-nham-dns-over-https-doh-voi-https" aria-label="Permalink to &quot;❌ Lỗi 46: Nhầm DNS over HTTPS (DoH) với HTTPS&quot;">​</a></h3><p><strong>Sai:</strong> &quot;DNS over HTTPS là DNS chạy qua website HTTPS.&quot;</p><p><strong>Đúng:</strong> <strong>DNS over HTTPS (DoH)</strong> là giao thức truyền DNS query qua kênh HTTPS (port 443) thay vì UDP port 53. Mục đích: mã hóa DNS query để ISP/network không thấy bạn đang tra cứu domain gì. Khác hoàn toàn với &quot;website HTTPS&quot; – DoH liên quan đến cách browser/OS tra cứu DNS.</p><hr><h3 id="❌-loi-47-nghi-cgi-va-php-la-giong-nhau" tabindex="-1">❌ Lỗi 47: Nghĩ CGI và PHP là giống nhau <a class="header-anchor" href="#❌-loi-47-nghi-cgi-va-php-la-giong-nhau" aria-label="Permalink to &quot;❌ Lỗi 47: Nghĩ CGI và PHP là giống nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;PHP và CGI là công nghệ web server-side giống nhau.&quot;</p><p><strong>Đúng:</strong> <strong>CGI (Common Gateway Interface)</strong> là chuẩn để web server chạy chương trình bên ngoài (có thể viết bằng bất kỳ ngôn ngữ: Perl, Python, C...). <strong>PHP</strong> là ngôn ngữ lập trình chuyên dùng cho web. PHP thường chạy qua PHP-FPM (không phải CGI truyền thống). PHP là ngôn ngữ, CGI là giao thức.</p><hr><h3 id="❌-loi-48-nham-wildcard-ssl-certificate-voi-standard-certificate" tabindex="-1">❌ Lỗi 48: Nhầm wildcard SSL certificate với standard certificate <a class="header-anchor" href="#❌-loi-48-nham-wildcard-ssl-certificate-voi-standard-certificate" aria-label="Permalink to &quot;❌ Lỗi 48: Nhầm wildcard SSL certificate với standard certificate&quot;">​</a></h3><p><strong>Sai:</strong> &quot;SSL certificate cho example.com cũng bảo vệ mail.example.com và blog.example.com.&quot;</p><p><strong>Đúng:</strong> <strong>Standard certificate</strong> chỉ bảo vệ domain cụ thể (và thường cả www.). <strong>Wildcard certificate</strong> (<code>*.example.com</code>) bảo vệ tất cả <strong>one-level subdomains</strong> (mail.example.com, blog.example.com) nhưng không bảo vệ example.com gốc hoặc sub-subdomain (a.b.example.com). Cần <strong>SAN certificate</strong> cho nhiều domain khác nhau.</p><hr><h3 id="❌-loi-49-nghi-websocket-la-http-lien-tuc" tabindex="-1">❌ Lỗi 49: Nghĩ WebSocket là HTTP liên tục <a class="header-anchor" href="#❌-loi-49-nghi-websocket-la-http-lien-tuc" aria-label="Permalink to &quot;❌ Lỗi 49: Nghĩ WebSocket là HTTP liên tục&quot;">​</a></h3><p><strong>Sai:</strong> &quot;WebSocket là giữ kết nối HTTP mở mãi mãi.&quot;</p><p><strong>Đúng:</strong> <strong>WebSocket</strong> là giao thức khác với HTTP. Nó bắt đầu bằng HTTP Upgrade request, nhưng sau khi thiết lập, trở thành kênh <strong>full-duplex, persistent, low-overhead</strong> cho phép server chủ động gửi data đến client (không cần client request). HTTP là request-response; WebSocket là bidirectional stream.</p><hr><h3 id="❌-loi-50-nghi-cloudflare-la-web-hosting" tabindex="-1">❌ Lỗi 50: Nghĩ Cloudflare là web hosting <a class="header-anchor" href="#❌-loi-50-nghi-cloudflare-la-web-hosting" aria-label="Permalink to &quot;❌ Lỗi 50: Nghĩ Cloudflare là web hosting&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dùng Cloudflare là lưu trữ website trên Cloudflare.&quot;</p><p><strong>Đúng:</strong> <strong>Cloudflare</strong> là dịch vụ <strong>CDN, DNS, và bảo vệ DDoS</strong> – không phải web hosting. Cloudflare đứng trước web server của bạn (reverse proxy), cache nội dung, lọc traffic độc hại, và tăng tốc website. Website vẫn cần lưu trữ trên hosting riêng. Cloudflare Pages/Workers là một dịch vụ khác có hosting tĩnh.</p>`,317)])])}const u=t(i,[["render",e]]);export{p as __pageData,u as default};
